/* HARDGATE — build stamp. Single source of truth for "which version am I running?"
   Loaded FIRST so every later script can read G.HG_BUILD. */
(function(){
'use strict';
var G = (typeof window !== 'undefined') ? window : globalThis;

var HG_BUILD = {
  version: 'hg-v908',
  pack: 'ALL THE GOLD TABS SAY WHEN THEIR TAPE IS NOT CONTINUOUS. Pack 907 asked whether each bar is one a market could have produced. It said nothing about whether the bars are CONSECUTIVE, and a feed can return two hundred perfectly well-formed bars with a run of them missing out of the middle. Every indicator in this app walks the array by index, so a hole means EMA, ATR and RSI are computed across a discontinuity and twenty bars ago is not twenty bars ago. MEASURED, WHAT A HOLE DOES: delete a contiguous run from a 220-bar 15m tape and re-run the app own atr/ema/rsi, 400 seeded tapes per cell, median shift. A hole ending 110 bars before the last bar moves ATR14 by 0.002% and RSI14 by 0.004%; at 40 bars, 0.23% and 0.60%; at 20 bars, 1.07% and 2.56%; at 10 bars, 2.60% and 4.54%; at 2 bars, 4.93% and 7.25%; a 48-bar hole 2 bars back moves ATR by 7.82% and RSI by 20.58%. The damage is almost entirely a function of HOW RECENT the hole is, so the note reports the distance and not just a count - an old hole has rolled out of the averaging window, a recent one moves ATR, and ATR is the distance the stop is placed at, which is the distance R is measured in and size is derived from. A first draft assumed a mid-tape hole distorted ATR; the measurement said 0.002% and the table replaced the assumption. MEASURED, WHAT THE FAMILY DID: driving the whole GOLD nav group on a tape with a 12-bar hole, FIVE of the fifteen that can be driven rendered different numbers and NOT ONE of the fifteen said a word. The only gap check anywhere in the tree was in gold-seven-step.js, on the 1H series, at a three-day threshold, so a hole of two days or less passed silently everywhere including there. THE WEEKEND IS NOT A HOLE. Gold shuts Friday evening to Sunday evening, and a rule that flagged every gap would fire every week and be ignored by the second one. Gaps are classified with the app OWN hgInGoldWeekend, the same DST-aware definition the weekend-exposure panel uses, rather than a second copy of the trading calendar. Verified silent on 28 realistic gold tapes (four timeframes by seven start weekdays) with 16 of 16 punched holes still caught, down to a single missing bar. ONE RULE, NO EDGE CASES: the missing count walks the slots and skips the closed ones, so a gap the weekend fully explains has zero missing bars and is not a hole, while a hole that starts at the Friday edge or runs through a closure is still a hole of exactly its own size. TWO DEFECTS THIS PACK FOUND IN ITSELF. First, an early draft counted round(gap / spacing) and reported a 48-bar hole that swallowed a weekend as 96 missing bars - true about wall-clock, false about bars, and the number a reader would act on. Second, the spacing was inferred from a strided sample, which smeared the closure into the estimate and returned 144000 instead of 86400 on a DAILY tape; the rule stayed silent, which looked like a pass, while a hole then had to exceed two and a half days to register at all. Consecutive gaps put the weekend in the tail where the median ignores it. THE THIRTEEN WIRED TABS now ask both tape questions through one hgGoldTapeNotes call, so a third rule lands in one place rather than thirteen. After the wiring, every tab that moves on a holed tape discloses it - nine disclose against five that move - no tab claims a hole on a continuous tape, and the two faults never stand in for one another. IT REPORTS; IT DOES NOT GATE. Nothing is filled in, interpolated or reconstructed, the check does not mutate the tape it reads, and the implementation holds no splice or insert for a silent fill to hide in. G1-G7, the gold stop floors and ceilings, the baked edge tables, the Wilson lower bound and the 80% accuracy floor are unchanged. Record only, nothing fetched or sent',
  built: '2026-09-20T00:00:00Z'
};

function hgBuildLabel(b){
  b = b || HG_BUILD;
  var v = String(b.version || '').replace(/^hg-/, '');
  var p = b.pack ? ' · ' + b.pack : '';
  return v ? v + p : 'unknown build';
}

function hgBuildParseVersion(text){
  try{
    if (typeof text !== 'string' || !text) return null;
    var m = text.match(/version\s*:\s*['"]([A-Za-z0-9._-]{1,64})['"]/);
    return m ? m[1] : null;
  }catch(e){ return null; }
}

function hgBuildCompare(loaded, live){
  if (!loaded || !live) return { state: 'unknown', reason: 'could not read one side' };
  if (String(loaded) === String(live)) return { state: 'fresh', reason: 'matches server' };
  return { state: 'stale', reason: 'server is on ' + live + ', this tab loaded ' + loaded };
}

function hgBuildDistance(loaded, live){
  try{
    var a = String(loaded || '').match(/(\d+)\s*$/);
    var b = String(live || '').match(/(\d+)\s*$/);
    if (!a || !b) return null;
    return (+b[1]) - (+a[1]);
  }catch(e){ return null; }
}

function hgBuildChipState(res, b){
  b = b || HG_BUILD;
  var label = hgBuildLabel(b);
  if (!res || res.state === 'pending') return { text: label, cls: 'ok', title: 'checking for newer build' };
  if (res.state === 'fresh') return { text: label, cls: 'ok', title: 'running current build (' + res.live + ')' };
  if (res.state === 'stale'){
    var d = hgBuildDistance(res.loaded, res.live);
    var behind = (d != null && d > 0) ? ' (' + d + ' behind)' : '';
    return { text: label + ' · STALE' + behind, cls: 'bad', title: res.reason + ' — hard-reload to pick it up' };
  }
  return { text: label + ' · ?', cls: 'warn', title: (res.reason || 'freshness unknown') + ' — offline or blocked' };
}

function hgBuildFreshness(fetchImpl){
  var f = (typeof fetchImpl === 'function') ? fetchImpl : (typeof G.fetch === 'function' ? G.fetch.bind(G) : null);
  var loaded = HG_BUILD.version;
  if (!f) return Promise.resolve({ state: 'unknown', loaded: loaded, live: null, reason: 'no fetch' });
  var url = './build-stamp.js?fresh=' + Date.now();
  return f(url, { cache: 'no-store' }).then(function(res){
    if (!res || !res.ok) throw new Error('http ' + (res && res.status));
    return res.text();
  }).then(function(text){
    var live = hgBuildParseVersion(text);
    var cmp = hgBuildCompare(loaded, live);
    return { state: cmp.state, loaded: loaded, live: live, reason: cmp.reason };
  }).catch(function(e){
    return { state: 'unknown', loaded: loaded, live: null, reason: (e && e.message) || 'network failed' };
  });
}

function hgBuildSwWaiting(){
  try{
    var sw = G.navigator && G.navigator.serviceWorker;
    if (!sw || !sw.controller) return Promise.resolve(false);
    return sw.getRegistration().then(function(reg){
      return !!(reg && reg.waiting);
    }).catch(function(){ return false; });
  }catch(e){ return Promise.resolve(false); }
}

function hgRenderBuildChip(el, res){
  try{
    var node = el || (G.document && G.document.getElementById('chipBuild'));
    if (!node) return null;
    var st = hgBuildChipState(res);
    node.textContent = '';
    var b = G.document.createElement('b');
    b.textContent = st.text;
    node.appendChild(b);
    node.title = st.title;
    node.className = 'statuschip hg-build-' + st.cls;
    return st;
  }catch(e){ return null; }
}

function hgRenderVerBadge(res){
  try{
    var node = G.document && G.document.getElementById('hgVerBadge');
    if (!node) return null;
    var v = String(HG_BUILD.version || '').replace(/^hg-/, '');
    if (!v){ node.style.display = 'none'; return null; }
    if (res && res.state === 'stale'){
      var d = hgBuildDistance(res.loaded, res.live);
      var behind = (d != null && d > 0) ? ' (' + d + ' behind)' : '';
      node.textContent = v + ' · STALE' + behind;
      node.className = 'verbadge verbadge-stale';
      node.title = (res.reason || 'stale') + ' — reloading…';
      return { stale: true };
    }
    node.textContent = v;
    node.className = 'verbadge';
    node.title = HG_BUILD.version + (HG_BUILD.pack ? (' · ' + HG_BUILD.pack) : '');
    return { stale: false };
  }catch(e){ return null; }
}

function hgBuildMaybeReload(res, storage, reloadFn){
  try{
    if (!res || res.state !== 'stale' || !res.live) return false;
    var store = storage;
    if (!store && G.sessionStorage) store = G.sessionStorage;
    if (!store || typeof store.getItem !== 'function') return false;
    var key = 'hg_build_reload_' + String(res.live);
    if (store.getItem(key)) return false;
    var reload = reloadFn;
    if (!reload && G.location && typeof G.location.reload === 'function') reload = G.location.reload.bind(G.location);
    if (typeof reload !== 'function') return false;
    store.setItem(key, '1');
    reload();
    return true;
  }catch(e){}
  return false;
}

function hgBuildApplyFreshness(res){
  try{
    if (!res) return res;
    hgRenderBuildChip(null, res);
    hgRenderVerBadge(res);
    G.HG_BUILD_FRESHNESS = res;
    hgBuildMaybeReload(res);
    return res;
  }catch(e){ return res; }
}

function hgBuildInit(){
  try{
    hgRenderBuildChip(null, null);
    hgRenderVerBadge(null);
    hgBuildFreshness().then(function(res){
      return hgBuildSwWaiting().then(function(waiting){
        if (waiting && res.state === 'fresh'){
          res = { state: 'stale', loaded: res.loaded, live: res.live, reason: 'new build downloaded' };
        }
        return hgBuildApplyFreshness(res);
      });
    });
    if (G.document && typeof G.document.addEventListener === 'function'){
      G.document.addEventListener('visibilitychange', function(){
        try{
          if (!G.document || G.document.visibilityState !== 'visible') return;
          hgBuildFreshness().then(hgBuildApplyFreshness);
        }catch(e){}
      });
    }
  }catch(e){}
}

G.HG_BUILD = HG_BUILD;
G.hgBuildLabel = hgBuildLabel;
G.hgBuildParseVersion = hgBuildParseVersion;
G.hgBuildCompare = hgBuildCompare;
G.hgBuildDistance = hgBuildDistance;
G.hgBuildChipState = hgBuildChipState;
G.hgBuildFreshness = hgBuildFreshness;
G.hgBuildSwWaiting = hgBuildSwWaiting;
G.hgRenderBuildChip = hgRenderBuildChip;
G.hgRenderVerBadge = hgRenderVerBadge;
G.hgBuildMaybeReload = hgBuildMaybeReload;
G.hgBuildApplyFreshness = hgBuildApplyFreshness;
G.hgBuildInit = hgBuildInit;

try{
  if (G.document){
    if (G.document.readyState === 'loading'){
      G.document.addEventListener('DOMContentLoaded', hgBuildInit);
    } else {
      hgBuildInit();
    }
  }
}catch(e){}

})();
